def busca(lista, chave):
    if len(lista) == 0:
        return False
    meio = len(lista) // 2
    if lista[meio] == chave:
        return True
    if lista[meio] < chave:
        return busca(lista[meio + 1:], chave)
    return busca(lista[:meio], chave)

print(busca([2, 5, 8, 11, 14, 17, 20], 17))

